function def_Log {
    param([string]$Level, [string]$Message)
    $ts = (Get-Date).ToString("HH:mm:ss.fff")
    $color = switch ($Level) {
        "OK"    { "Green" }
        "WARN"  { "Yellow" }
        "FAIL"  { "Red" }
        "RUN"   { "Cyan" }
        "PHASE" { "Magenta" }
        "INFO"  { "White" }
        "DRY"   { "DarkYellow" }
        default { "Gray" }
    }
    Write-Host "[$ts] [$Level] $Message" -ForegroundColor $color
    [void]$script:State.PhaseLog.Add([pscustomobject]@{
        Timestamp = $ts; Level = $Level; Message = $Message
    })
}

