function def_FindPython {
    $candidates = @(
        "C:\Users\tonyk\envs\via_core_312\Scripts\python.exe",
        "C:\Users\tonyk\envs\via_core\Scripts\python.exe",
        "C:\Python313\python.exe",
        "C:\Python312\python.exe"
    )
    foreach ($p in $candidates) {
        if (Test-Path -LiteralPath $p) { return $p }
    }
    $py = Get-Command python -ErrorAction SilentlyContinue
    if ($py) { return $py.Source }
    throw "Python not found"
}

function def_WriteB64ToFile {
    param([string]$B64Text, [string]$TargetPath)
    $clean = $B64Text -replace "`r","" -replace "`n","" -replace " ",""
    $bytes = [Convert]::FromBase64String($clean)
    $text  = [System.Text.UTF8Encoding]::new($false).GetString($bytes)
    if ([string]::IsNullOrWhiteSpace($text)) { throw "Empty after decode for $TargetPath" }
    $targetDir = Split-Path $TargetPath -Parent
    if (-not (Test-Path -LiteralPath $targetDir)) {
        New-Item -ItemType Directory -Force -Path $targetDir | Out-Null
    }
    [System.IO.File]::WriteAllText($TargetPath, $text, [System.Text.UTF8Encoding]::new($false))
    return $text.Length
}

function def_ParseJsonOutput {
    param([string]$RawOutput)
    $lines = $RawOutput -split "`r?`n"
    $jsonStart = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -match '^\s*\{') { $jsonStart = $i; break }
    }
    if ($jsonStart -lt 0) { return $null }
    $jsonText = ($lines[$jsonStart..($lines.Count - 1)] -join "`n").Trim()
    try { return ($jsonText | ConvertFrom-Json -Depth 20) } catch { return $null }
}

function def_HtmlEscape {
    param([string]$Text)
    if ($null -eq $Text) { return "" }
    return $Text -replace '&','&amp;' -replace '<','&lt;' -replace '>','&gt;' -replace '"','&quot;'
}

