function def_Phase1_Environment {
    def_Log "PHASE" "Phase 1: Environment"
    $script:State.PS7Version = "$($PSVersionTable.PSVersion)"
    if ($PSVersionTable.PSVersion.Major -lt 7) { throw "Requires PS7+" }
    def_Log "OK" "PS7 $($script:State.PS7Version)"

    if (-not (Test-Path -LiteralPath $AegisPath)) {
        throw "Aegis not found: $AegisPath"
    }
    if (-not (Test-Path -LiteralPath $EnvMgrPath)) {
        throw "EnvManager not found: $EnvMgrPath"
    }
    $script:State.AegisPath = $AegisPath
    $script:State.EnvMgrPath = $EnvMgrPath
    def_Log "OK" "Aegis:    $AegisPath"
    def_Log "OK" "EnvMgr:   $EnvMgrPath"

    $py = def_FindPython
    $script:State.Python = $py
    def_Log "OK" "Python: $py"
    [void]$script:State.CompletedPhases.Add("Phase 1: Environment")
}

function def_Phase2_WritePayloads {
    def_Log "PHASE" "Phase 2: Write payloads"
    $orchPath = Join-Path $script:DownloadsDir "VRN_v139G_Orchestrator.py"
    $anchorPath = Join-Path $script:DownloadsDir "V139G_AnchorBlock.py"
    $orchSize = def_WriteB64ToFile -B64Text $script:OrchestratorB64 -TargetPath $orchPath
    $anchorSize = def_WriteB64ToFile -B64Text $script:AnchorB64 -TargetPath $anchorPath
    $script:State.OrchestratorPath = $orchPath
    $script:State.AnchorPath = $anchorPath
    def_Log "OK" "Orchestrator: $orchPath ($orchSize bytes)"
    def_Log "OK" "Anchor:       $anchorPath ($anchorSize bytes)"

    $r = & $script:State.Python -m py_compile $orchPath 2>&1
    if ($LASTEXITCODE -ne 0) { throw "Orchestrator compile failed: $($r -join '; ')" }
    $r = & $script:State.Python -m py_compile $anchorPath 2>&1
    if ($LASTEXITCODE -ne 0) { throw "Anchor compile failed: $($r -join '; ')" }
    def_Log "OK" "Both payloads compile clean"
    [void]$script:State.CompletedPhases.Add("Phase 2: Write payloads")
}

function def_InvokeOrchestrator {
    param([string]$Cmd, [string[]]$ExtraArgs)
    $argList = @($script:State.OrchestratorPath, $Cmd) + $ExtraArgs
    $rawOut = & $script:State.Python @argList 2>&1
    $exitCode = $LASTEXITCODE
    $rawStr = ($rawOut | Out-String)
    if ($exitCode -ne 0) {
        throw "Orchestrator $Cmd failed exit=$exitCode : $rawStr"
    }
    $parsed = def_ParseJsonOutput -RawOutput $rawStr
    if (-not $parsed) {
        throw "Could not parse JSON for $Cmd. Raw: $($rawStr.Substring(0, [Math]::Min(500, $rawStr.Length)))"
    }
    return $parsed
}

function def_Phase3_DiagnoseAegis {
    def_Log "PHASE" "Phase 3: Diagnose Aegis"
    $diag = def_InvokeOrchestrator -Cmd "diagnose-aegis" -ExtraArgs @("--aegis", $script:State.AegisPath)
    $script:State.Diagnose = $diag

    def_Log "INFO" "File: $($diag.size_bytes) bytes, $($diag.lines) lines"
    def_Log "INFO" "AST parseable: $($diag.ast_parseable)"
    def_Log "INFO" "Top-level classes: $($diag.top_level_classes), functions: $($diag.top_level_functions)"
    def_Log "INFO" "LibraryRegistry present: $($diag.library_registry_present)"
    def_Log "INFO" "yFinanceShield present: $($diag.yfinance_shield_present)"

    if ($diag.anchor_already_present) {
        def_Log "WARN" "V139G anchor already present ($($diag.anchor_already_count) occurrence) - will idempotent-skip append"
    } else {
        def_Log "OK" "V139G anchor not yet present - will append"
    }

    if (-not $diag.ast_parseable) {
        throw "Aegis has syntax errors before patching: $($diag.ast_error)"
    }
    [void]$script:State.CompletedPhases.Add("Phase 3: Diagnose Aegis")
}

function def_Phase4_AppendAnchor {
    def_Log "PHASE" "Phase 4: Append anchor to Aegis"
    $extraArgs = @(
        "--aegis", $script:State.AegisPath,
        "--anchor", $script:State.AnchorPath,
        "--backup-stamp", $script:STAMP
    )
    if ($DryRun) { $extraArgs += "--dry-run" }

    $res = def_InvokeOrchestrator -Cmd "append-anchor" -ExtraArgs $extraArgs
    $script:State.AppendResult = $res

    if (-not $res.ok) {
        $errStr = if ($res.errors) { $res.errors -join '; ' } else { '(no errors but ok=false)' }
        throw "Append failed: $errStr"
    }

    if ($res.already_present) {
        def_Log "INFO" "Anchor already present - idempotent skip"
    } else {
        def_Log "OK" "Anchor appended: $($res.lines_before) -> $($res.lines_after) lines"
        def_Log "OK" "Backup: $($res.backup)"
        def_Log "OK" "SHA before: $(([string]$res.sha_before).Substring(0,16))..."
        def_Log "OK" "SHA after:  $(([string]$res.sha_after).Substring(0,16))..."
    }

    if ($DryRun) {
        def_Log "DRY" "DryRun - file NOT actually modified"
        return
    }

    # py_compile verify the modified Aegis
    $r = & $script:State.Python -m py_compile $script:State.AegisPath 2>&1
    if ($LASTEXITCODE -ne 0) {
        def_Log "FAIL" "Aegis py_compile FAILED after append:"
        def_Log "FAIL" ($r -join "`n")
        if ($res.backup) {
            Copy-Item -LiteralPath $res.backup -Destination $script:State.AegisPath -Force
            def_Log "OK" "Rolled back from $($res.backup)"
        }
        throw "Aegis py_compile failed after append; rolled back"
    }
    def_Log "OK" "Aegis py_compile clean after append"
    [void]$script:State.CompletedPhases.Add("Phase 4: Append anchor")
}

function def_Phase5_SmokeAnchor {
    def_Log "PHASE" "Phase 5: Smoke test anchor"
    if ($DryRun) {
        def_Log "DRY" "Skipping smoke (DryRun)"
        return
    }
    $res = def_InvokeOrchestrator -Cmd "smoke-anchor" -ExtraArgs @("--aegis", $script:State.AegisPath)
    $script:State.SmokeResult = $res
    if ($res.ok) {
        def_Log "OK" "All $($res.exports_found.Count) exports present"
        def_Log "OK" "def_advise_libs() returns $($res.advise_libs_count) libs"
    } else {
        def_Log "FAIL" "Missing exports: $($res.exports_missing -join ', ')"
        foreach ($e in $res.errors) { def_Log "FAIL" "Error: $e" }
        throw "Smoke test failed"
    }
    [void]$script:State.CompletedPhases.Add("Phase 5: Smoke anchor")
}

function def_Phase6_EmitLibs {
    def_Log "PHASE" "Phase 6: Emit lib list"
    if ($DryRun) {
        def_Log "DRY" "Skipping (DryRun)"
        return
    }
    $libsPath = Join-Path $script:DownloadsDir "v139g_libs.json"
    $res = def_InvokeOrchestrator -Cmd "emit-libs-json" -ExtraArgs @(
        "--aegis", $script:State.AegisPath,
        "--out", $libsPath
    )
    $script:State.EmitResult = $res
    $script:State.LibsJsonPath = $libsPath
    if ($res.ok) {
        def_Log "OK" "Wrote $($res.libs_written) libs to $libsPath"
    } else {
        throw "Emit libs failed: $($res.error)"
    }
    [void]$script:State.CompletedPhases.Add("Phase 6: Emit libs")
}

function def_Phase7_PlanInstall {
    def_Log "PHASE" "Phase 7: Plan installs (dry-gating via EnvManager)"
    if ($DryRun -or $SkipInstall) {
        def_Log "INFO" "Skipping (DryRun or -SkipInstall)"
        return
    }
    $res = def_InvokeOrchestrator -Cmd "plan-install" -ExtraArgs @(
        "--envmgr", $script:State.EnvMgrPath,
        "--libs", $script:State.LibsJsonPath
    )
    $script:State.PlanResult = $res
    def_Log "OK" "Plans generated: $($res.plans.Count)"
    $approved = @($res.plans | Where-Object { $_.approved }).Count
    def_Log "INFO" "Approved by EnvManager: $approved / $($res.plans.Count)"
    [void]$script:State.CompletedPhases.Add("Phase 7: Plan installs")
}

function def_Phase8_ExecuteInstall {
    def_Log "PHASE" "Phase 8: Execute installs"
    if ($DryRun -or $SkipInstall) {
        def_Log "INFO" "Skipping (DryRun or -SkipInstall)"
        return
    }
    $extraArgs = @(
        "--envmgr", $script:State.EnvMgrPath,
        "--libs", $script:State.LibsJsonPath
    )
    if ($MaxInstalls -gt 0) {
        $extraArgs += "--max"
        $extraArgs += "$MaxInstalls"
    }
    $res = def_InvokeOrchestrator -Cmd "execute-install" -ExtraArgs $extraArgs
    $script:State.InstallResult = $res
    def_Log "OK" "Processed: $($res.libs_processed) / $($res.libs_total)"
    def_Log "INFO" "Approved=$($res.summary.approved) Installed=$($res.summary.installed) ImportOK=$($res.summary.import_ok) Skipped=$($res.summary.skipped) Failed=$($res.summary.failed)"
    [void]$script:State.CompletedPhases.Add("Phase 8: Execute installs")
}

function def_Phase9_VerifyImports {
    def_Log "PHASE" "Phase 9: Verify imports across envs"
    if ($DryRun -or $SkipInstall) {
        def_Log "INFO" "Skipping (DryRun or -SkipInstall)"
        return
    }
    $res = def_InvokeOrchestrator -Cmd "verify-imports" -ExtraArgs @(
        "--envmgr", $script:State.EnvMgrPath,
        "--libs", $script:State.LibsJsonPath
    )
    $script:State.VerifyResult = $res
    $totalImports = ($res.results | ForEach-Object { $_.found_in.Count } | Measure-Object -Sum).Sum
    def_Log "OK" "Lib-env import probes: $totalImports total successful imports across $($res.results.Count) libs"
    [void]$script:State.CompletedPhases.Add("Phase 9: Verify imports")
}

function def_Phase10_HtmlMatrix {
    def_Log "PHASE" "Phase 10: HTML Matrix report"
    $reportPath = Join-Path $script:DownloadsDir "VRN_v139G_Matrix_Report_$($script:STAMP).html"

    $diag = $script:State.Diagnose
    $append = $script:State.AppendResult
    $smoke = $script:State.SmokeResult
    $plan = $script:State.PlanResult
    $install = $script:State.InstallResult
    $verify = $script:State.VerifyResult

    $elapsed = [math]::Round(((Get-Date) - $script:T0).TotalSeconds, 2)
    $overallStatus = if ($script:State.FatalError) { "FAILED" } elseif ($DryRun) { "DRY_RUN" } elseif ($SkipInstall) { "ANCHOR_ONLY" } elseif ($install -and $install.summary.failed -gt 0) { "PARTIAL" } else { "PASS" }
    $statusColor = switch ($overallStatus) {
        "PASS"        { "#10b981" }
        "PARTIAL"     { "#f59e0b" }
        "ANCHOR_ONLY" { "#4c78a8" }
        "DRY_RUN"     { "#8b5cf6" }
        "FAILED"      { "#ef4444" }
        default       { "#64748b" }
    }

    # Tab 1: Overview phases
    $phasesRows = ""
    foreach ($p in $script:State.CompletedPhases) {
        $phasesRows += "<tr><td>$(def_HtmlEscape $p)</td><td class='ok'>completed</td></tr>"
    }
    if ($script:State.FatalError) {
        $phasesRows += "<tr><td>FATAL: $(def_HtmlEscape $script:State.FatalError)</td><td class='bad'>failed</td></tr>"
    }

    # Tab 2: Diagnose
    $diagHtml = "(not run)"
    if ($diag) {
        $diagHtml = @"
<table class="tbl">
<tr><th>Property</th><th>Value</th></tr>
<tr><td>File size</td><td>$($diag.size_bytes) bytes</td></tr>
<tr><td>Lines</td><td>$($diag.lines)</td></tr>
<tr><td>AST parseable</td><td>$($diag.ast_parseable)</td></tr>
<tr><td>Top-level classes</td><td>$($diag.top_level_classes)</td></tr>
<tr><td>Top-level functions</td><td>$($diag.top_level_functions)</td></tr>
<tr><td>LibraryRegistry present</td><td>$($diag.library_registry_present)</td></tr>
<tr><td>yFinanceShield present</td><td>$($diag.yfinance_shield_present)</td></tr>
<tr><td>V139G anchor already present</td><td>$($diag.anchor_already_present)</td></tr>
<tr><td>Module metadata present</td><td>$($diag.module_metadata_present)</td></tr>
</table>
"@
    }

    # Tab 3: Append
    $appendHtml = "(not run)"
    if ($append) {
        $shaBeforeShort = if ($append.sha_before) { ([string]$append.sha_before).Substring(0,16) } else { "" }
        $shaAfterShort = if ($append.sha_after) { ([string]$append.sha_after).Substring(0,16) } else { "" }
        $appendHtml = @"
<table class="tbl">
<tr><th>Field</th><th>Value</th></tr>
<tr><td>OK</td><td>$($append.ok)</td></tr>
<tr><td>Already present (skip)</td><td>$($append.already_present)</td></tr>
<tr><td>Backup</td><td><code>$(def_HtmlEscape $append.backup)</code></td></tr>
<tr><td>SHA before</td><td><code>$shaBeforeShort...</code></td></tr>
<tr><td>SHA after</td><td><code>$shaAfterShort...</code></td></tr>
<tr><td>Lines before -> after</td><td>$($append.lines_before) -> $($append.lines_after)</td></tr>
</table>
"@
    }

    # Tab 4: Smoke
    $smokeHtml = "(not run)"
    if ($smoke) {
        $foundList = if ($smoke.exports_found) { ($smoke.exports_found | ForEach-Object { "<li><code>$_</code></li>" }) -join "" } else { "" }
        $smokeHtml = @"
<div class="sg">
