                $installRows += "<tr><td><code>$(def_HtmlEscape $r.lib)</code></td><td>$okCell</td><td>$(def_HtmlEscape $r.target_env)</td><td>$($r.elapsed_s)s</td><td>$(def_HtmlEscape $r.skipped_reason)$(def_HtmlEscape $r.error)</td></tr>"
            }
        }
        $sumApproved = if ($install) { $install.summary.approved } else { "n/a" }
        $sumInstalled = if ($install) { $install.summary.installed } else { "n/a" }
        $sumImport = if ($install) { $install.summary.import_ok } else { "n/a" }
        $sumSkipped = if ($install) { $install.summary.skipped } else { "n/a" }
        $sumFailed = if ($install) { $install.summary.failed } else { "n/a" }
        $planExecHtml = @"
