<table class="tbl">
<thead><tr><th>lib</th><th>approved</th><th>target_env</th><th>risk</th><th>blocked_reason</th></tr></thead>
<tbody>$planRows</tbody>
</table>
<h4>EnvManager execute-install results</h4>
<div class="sg">
<div class="sc"><div class="k">Approved</div><div class="v">$sumApproved</div></div>
<div class="sc ok"><div class="k">Installed</div><div class="v">$sumInstalled</div></div>
<div class="sc ok"><div class="k">Import OK</div><div class="v">$sumImport</div></div>
<div class="sc warn"><div class="k">Skipped</div><div class="v">$sumSkipped</div></div>
<div class="sc bad"><div class="k">Failed</div><div class="v">$sumFailed</div></div>
</div>
<table class="tbl">
<thead><tr><th>lib</th><th>status</th><th>target_env</th><th>elapsed</th><th>notes</th></tr></thead>
<tbody>$installRows</tbody>
</table>
"@
    }

    # Tab 7: Verify imports
    $verifyHtml = "(not run)"
    if ($verify -and $verify.results) {
        $verifyRows = ""
        foreach ($v in $verify.results) {
            $envList = if ($v.found_in) { ($v.found_in -join ", ") } else { "<i>(no env has it)</i>" }
            $foundCount = $v.found_in.Count
            $cls = if ($foundCount -ge 1) { "ok" } else { "bad" }
            $verifyRows += "<tr class='$cls'><td><code>$(def_HtmlEscape $v.lib)</code></td><td><code>$(def_HtmlEscape $v.module)</code></td><td>$foundCount</td><td>$(def_HtmlEscape $envList)</td></tr>"
        }
        $verifyHtml = @"
<p><b>Per-lib import probe across all detected envs</b></p>
<table class="tbl">
<thead><tr><th>lib</th><th>module</th><th>envs_with_import</th><th>found_in</th></tr></thead>
<tbody>$verifyRows</tbody>
</table>
"@
    }

    # Tab 8: Phase log
    $logRows = ""
    foreach ($entry in $script:State.PhaseLog) {
        $cls = switch ($entry.Level) {
            "OK"    { "ok" }
            "WARN"  { "warn" }
            "FAIL"  { "bad" }
            "PHASE" { "phase" }
            default { "" }
        }
        $logRows += "<tr class='$cls'><td class='mono'>$(def_HtmlEscape $entry.Timestamp)</td><td>$(def_HtmlEscape $entry.Level)</td><td>$(def_HtmlEscape $entry.Message)</td></tr>"
    }

    $errorHtml = if ($script:State.FatalError) {
        "<pre style='color:#ef4444'>$(def_HtmlEscape $script:State.FatalError)</pre><pre>$(def_HtmlEscape $script:State.FatalStack)</pre>"
    } else {
        "<p class='ok'>No fatal errors. All phases that ran completed.</p>"
    }

    $html = @"
<!doctype html><html><head><meta charset="utf-8">
<title>VRN v139G Matrix Report - $($script:STAMP)</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f5f4f0;color:#111827;
  font-family:'DM Sans','Segoe UI','Microsoft JhengHei',Arial,sans-serif;font-size:12px}
header{background:#0f172a;color:white;padding:24px 32px;
  border-top:4px solid;border-image:linear-gradient(90deg,#ef4444,#f59e0b,#10b981,#4c78a8,#8b5cf6) 1}
h1{margin:0;font-family:'Syne',serif;font-size:24px;color:white;display:flex;align-items:center;gap:12px}
.bdg{padding:4px 12px;border-radius:3px;font-family:'DM Mono',monospace;font-size:11px;font-weight:700;color:white}
.sub{color:#cbd5e1;margin:8px 0 0;font-family:'DM Mono',monospace;font-size:10.5px}
main{padding:20px 32px;max-width:1500px;margin:0 auto}
.tabs{display:flex;gap:2px;border-bottom:2px solid #0f172a;flex-wrap:wrap}
.tab{padding:10px 16px;background:#e5e7eb;border-radius:5px 5px 0 0;cursor:pointer;
  font-family:'DM Mono',monospace;font-size:11px;font-weight:700;color:#374151;border:none}
.tab.active{background:#0f172a;color:#fbbf24}
.tab:hover:not(.active){background:#cbd5e1}
.tab-content{display:none;background:white;padding:20px;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 6px 6px;min-height:300px}
.tab-content.active{display:block}
.cd-h{font-family:'Syne',serif;font-size:14px;font-weight:700;margin:14px 0 10px;color:#0f172a;border-bottom:1px solid #e5e7eb;padding-bottom:4px}
.sg{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:14px}
.sc{background:#f5f4f0;border:1px solid #e5e7eb;border-radius:6px;padding:12px}
.sc .k{font-size:9px;color:#64748b;font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:.5px}
.sc .v{font-size:18px;font-weight:800;margin-top:4px;font-family:'DM Mono',monospace;color:#4c78a8}
.sc.ok .v{color:#047857}.sc.warn .v{color:#b45309}.sc.bad .v{color:#b91c1c}
.tbl{width:100%;border-collapse:collapse;font-family:'DM Mono',monospace;font-size:10.5px;margin-bottom:10px}
.tbl th{background:#1f2937;color:white;text-align:left;padding:6px 9px;font-family:'DM Sans',sans-serif;font-size:11px}
.tbl td{padding:5px 9px;border-bottom:1px solid #e5e7eb;vertical-align:top}
.tbl tr:nth-child(even):not(.warn):not(.bad):not(.phase){background:#fafaf8}
.tbl tr.warn{background:#fef3c7}.tbl tr.bad{background:#fee2e2}.tbl tr.phase{background:#ede9fe;font-weight:700}
.ok{color:#047857;font-weight:700}.bad{color:#b91c1c;font-weight:700}.warn{color:#b45309;font-weight:700}
.mono{font-family:'DM Mono',monospace}
code{background:#eef2ff;color:#3730a3;padding:1px 5px;border-radius:3px;font-family:'DM Mono',monospace;font-size:10.5px}
pre{background:#0f172a;color:#fbbf24;padding:12px;border-radius:5px;overflow-x:auto;font-family:'DM Mono',monospace;font-size:10.5px;white-space:pre-wrap}
h4{font-family:'Syne',serif;font-size:13px;margin:14px 0 6px;color:#0f172a}
ul{margin:6px 0;padding-left:24px}
</style></head><body>
<header>
<h1>VRN v1.0.39G TW Coverage Expansion <span class="bdg" style="background:$statusColor">$overallStatus</span></h1>
<div class="sub">$($script:STAMP) · elapsed=${elapsed}s · phases completed: $($script:State.CompletedPhases.Count)/10 · PS7 $($script:State.PS7Version)</div>
</header>
<main>

<div class="tabs">
<button class="tab active" onclick="showTab(0)">1. Overview</button>
<button class="tab" onclick="showTab(1)">2. Diagnose</button>
<button class="tab" onclick="showTab(2)">3. Append</button>
<button class="tab" onclick="showTab(3)">4. Smoke</button>
<button class="tab" onclick="showTab(4)">5. 20-lib Advisor</button>
<button class="tab" onclick="showTab(5)">6. Plan+Execute</button>
<button class="tab" onclick="showTab(6)">7. Verify Imports</button>
<button class="tab" onclick="showTab(7)">8. Phase Log + Errors</button>
</div>

<div class="tab-content active">
<div class="cd-h">def_Pipeline_Overview</div>
<div class="sg">
<div class="sc"><div class="k">Status</div><div class="v" style="color:$statusColor;font-size:14px">$overallStatus</div></div>
<div class="sc"><div class="k">Elapsed</div><div class="v">${elapsed}s</div></div>
