<table class="tbl"><thead><tr><th>Time</th><th>Level</th><th>Message</th></tr></thead><tbody>$logRows</tbody></table>
<div class="cd-h">def_Errors_Fatals</div>
$errorHtml
</div>

</main>
<script>
function showTab(idx){
  document.querySelectorAll('.tab').forEach((t,i)=>t.classList.toggle('active',i===idx));
  document.querySelectorAll('.tab-content').forEach((t,i)=>t.classList.toggle('active',i===idx));
}
</script>
</body></html>
"@
    [System.IO.File]::WriteAllText($reportPath, $html, [System.Text.UTF8Encoding]::new($false))
    def_Log "OK" "Matrix report: $reportPath"
    try {
        Start-Process $reportPath
        def_Log "OK" "Browser launched"
    } catch {
        def_Log "WARN" "Could not auto-open browser: $($_.Exception.Message)"
    }
    [void]$script:State.CompletedPhases.Add("Phase 10: HTML Matrix")
    return $reportPath
}

# ======================================================================
# def 04_MAIN
# ======================================================================

try {
    def_Phase1_Environment
    def_Phase2_WritePayloads
    def_Phase3_DiagnoseAegis
    def_Phase4_AppendAnchor
    def_Phase5_SmokeAnchor
    def_Phase6_EmitLibs
    def_Phase7_PlanInstall
    def_Phase8_ExecuteInstall
    def_Phase9_VerifyImports
} catch {
    $script:State.FatalError = $_.Exception.Message
    $script:State.FatalStack = $_.ScriptStackTrace
    Write-Host ""
    Write-Host "==================================================================================================" -ForegroundColor Red
    Write-Host "  [FATAL] $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "==================================================================================================" -ForegroundColor Red
    Write-Host $_.ScriptStackTrace -ForegroundColor DarkRed
}

# Phase 10 always runs
try {
    $reportPath = def_Phase10_HtmlMatrix
    Write-Host ""
    Write-Host "==================================================================================================" -ForegroundColor Cyan
    Write-Host "  HTML Matrix Report (auto-opened)" -ForegroundColor Cyan
    Write-Host "==================================================================================================" -ForegroundColor Cyan
    Write-Host "  $reportPath" -ForegroundColor Green
} catch {
    Write-Host "[WARN] HTML matrix generation failed: $($_.Exception.Message)" -ForegroundColor Yellow
}

Write-Host ""
Write-Host "Total elapsed: $([math]::Round(((Get-Date) - $script:T0).TotalSeconds, 2))s" -ForegroundColor Cyan
Write-Host "PowerShell session remains open." -ForegroundColor Cyan

